package com.wissenup.domain.timetable.entity;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="timetable_periods") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor
public class TimetablePeriod { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="period_id") private Long periodId; @Column(name="organization_id") private Long organizationId; @Column(name="period_name") private String periodName; @Column(name="start_time") private LocalTime startTime; @Column(name="end_time") private LocalTime endTime; @Column(name="is_break") private Boolean isBreak; @Column(name="display_order") private Integer displayOrder; private String status; @Column(name="created_at") private LocalDateTime createdAt; @Column(name="created_by") private Long createdBy; @Column(name="updated_at") private LocalDateTime updatedAt; @Column(name="updated_by") private Long updatedBy; @PrePersist void create(){if(status==null)status="ACTIVE";if(isBreak==null)isBreak=false;if(createdAt==null)createdAt=LocalDateTime.now();} @PreUpdate void update(){updatedAt=LocalDateTime.now();} }
